"""Single source of truth for table schemas and the data dictionary.

Every published column must be listed here (validate.py fails otherwise). The writer casts files to
these types, and docs/DATA_DICTIONARY.md + metadata/data_dictionary.json are generated from it.
Types: str, int16, int32, int64, float32, float64, bool, date, ts (timestamp ms, UTC).
"""
from __future__ import annotations

import pyarrow as pa

PA = {"str": pa.string(), "int16": pa.int16(), "int32": pa.int32(), "int64": pa.int64(), "float32": pa.float32(),
      "float64": pa.float64(), "bool": pa.bool_(), "date": pa.date32(), "ts": pa.timestamp("ms", tz="UTC")}


def C(name, typ, unit, nullable, desc, values=None):
    return {"name": name, "type": typ, "unit": unit, "nullable": nullable, "description": desc, "values": values}


SYN = C("synthetic", "bool", None, False, "Always true: the record is invented.")

