# private label copies share the dev schemas
for t in ("anomaly_labels", "reference_economics", "reference_economics_monthly", "reference_charge_lines", "decision_truth", "decision_outcomes",
          "operator_scorecard", "operator_action_values"):
    TABLES[f"labels_test/{t}"] = {**TABLES[f"labels_dev/{t}"], "pkg": "private"}
TABLES["benchmark/decision_cases_private"] = {**TABLES["benchmark/decision_cases"], "pkg": "private"}


def table_key(rel_path: str) -> str | None:
    """Map a file path inside a package to a schema key."""
    p = rel_path.replace("\\", "/")
    for pre in ("holdout_full/", ):
        if p.startswith(pre):
            p = p[len(pre):]
    if p.startswith("holdout_asof_"):
        p = p.split("/", 1)[1]
    if "/month=" in p:
        p = p.split("/month=")[0]
    if p.endswith(".parquet"):
        p = p[:-8]
    return p if p in TABLES else None


def arrow_schema(key: str) -> pa.Schema:
    return pa.schema([pa.field(c["name"], PA[c["type"]], nullable=True) for c in TABLES[key]["cols"]])
